import type { RegistryEntry } from "./jobs";
import data from "./registry/companies.json";
import type { Provider } from "./sources/types";

// The verified company list, generated by `npm run registry:verify`
// (scripts/verify-registry.ts). Every board in it returned live jobs,
// including software roles, when it was last verified.

export type RegistryFile = {
  verifiedAt: string;
  companies: { name: string; provider: Provider; board: string; careersUrl: string | null; jobs: number; softwareJobs: number }[];
  unsupported: { name: string; ats: string; careersUrl: string | null; note?: string }[];
  notFound: string[];
};

export const registry = data as RegistryFile;

export const registryEntries = (): RegistryEntry[] =>
  registry.companies.map((c) => ({ name: c.name, provider: c.provider, board: c.board, careersUrl: c.careersUrl }));
